// ten = "name", sdt = "phone number", gio = "hour"
// Each case: [order, "ok" or "error"]. Add cases until all five faulty versions are caught.
const testCases = [
  [{ ten: "An", sdt: "0901234567", gio: 9 }, "ok"],
];

// ---- Grading part, no need to read or edit ----
const standard = (d) =>
  d.ten.trim() === "" ? "error"
  : !/^0\d{9}$/.test(d.sdt) ? "error"
  : d.gio < 7 || d.gio > 21 ? "error" : "ok";
const buggy = [
  ["wrong at hour 21", (d) => (d.ten.trim() === "" || !/^0\d{9}$/.test(d.sdt) || d.gio < 7 || d.gio >= 21 ? "error" : "ok")],
  ["accepts an 11-digit phone number", (d) => (d.ten.trim() === "" || !/^0\d{9,10}$/.test(d.sdt) || d.gio < 7 || d.gio > 21 ? "error" : "ok")],
  ["accepts a name made only of spaces", (d) => (!d.ten || !/^0\d{9}$/.test(d.sdt) || d.gio < 7 || d.gio > 21 ? "error" : "ok")],
  ["accepts a number not starting with 0", (d) => (d.ten.trim() === "" || !/^\d{10}$/.test(d.sdt) || d.gio < 7 || d.gio > 21 ? "error" : "ok")],
  ["wrong at hour 22", (d) => (d.ten.trim() === "" || !/^0\d{9}$/.test(d.sdt) || d.gio < 7 || d.gio > 22 ? "error" : "ok")],
];
const passesAll = (f) => testCases.every(([order, expected]) => f(order) === expected);
console.log("Standard version passes all your cases: " + (passesAll(standard) ? "yes" : "no"));
for (const [name, f] of buggy) {
  console.log("Faulty version (" + name + "): " + (passesAll(f) ? "slipped through" : "caught"));
}

